module.exports={prepare,apply,verify,tests,finalize,rollback,release,CONFIG};
if(require.main===module){try{const [cmd,a,b]=process.argv.slice(2);if(cmd==='prepare')prepare(a,b);else if(['apply','verify','tests','finalize','rollback','release'].includes(cmd))module.exports[cmd](a);else fail('Unknown command.');}catch(e){console.error(e.message);process.exitCode=1;}}
